 * 灵魂知识库的文件存储。
 * U 盘场景约束：写操作全部原子化（tmp+rename），JSON 写入前留 .bak，
 * 主文件损坏时自动回退备份——拔盘瞬间写坏只丢一次变更，不丢整个库。
 */
import { mkdir, readdir, readFile, rename, copyFile, rm, writeFile } from "node:fs/promises"
import { dirname, join } from "node:path"

export const paths = (root: string) => ({
  people: join(root, "people"),
  events: join(root, "events"),
  facts: join(root, "facts"),
  seeds: join(root, "seeds.json"),
  temperament: join(root, "temperament.json"),
  index: join(root, "MEMORY.md"),
})

export async function ensure(root: string): Promise<void> {
  const layout = paths(root)
  await mkdir(layout.people, { recursive: true })
  await mkdir(layout.events, { recursive: true })
  await mkdir(layout.facts, { recursive: true })
}

export async function readJson<T>(file: string, fallback: T): Promise<T> {
  const main = await readFile(file, "utf8")
    .then((raw) => JSON.parse(raw) as T)
    .catch(() => undefined)
  if (main !== undefined) return main
  return readFile(`${file}.bak`, "utf8")
    .then((raw) => JSON.parse(raw) as T)
    .catch(() => fallback)
}

export async function writeJson(file: string, data: unknown): Promise<void> {
  await atomic(file, JSON.stringify(data, null, 2) + "\n")
  // 写入成功后再刷新 .bak，使备份始终是"最后一次完好的写入"
  await copyFile(file, `${file}.bak`).catch(() => {})
}

export async function writeText(file: string, content: string): Promise<void> {
  await atomic(file, content)
}

export async function readText(file: string): Promise<string | undefined> {
  return readFile(file, "utf8").catch(() => undefined)
}

export async function remove(file: string): Promise<void> {
  await rm(file, { force: true })
}

export async function listMd(dir: string): Promise<string[]> {
  const entries = await readdir(dir, { withFileTypes: true, recursive: true }).catch(() => [])
  return entries
    .filter((entry) => entry.isFile() && entry.name.endsWith(".md"))
    .map((entry) => join(entry.parentPath, entry.name))
    .sort()
}

async function atomic(file: string, content: string): Promise<void> {
  await mkdir(dirname(file), { recursive: true })
  const tmp = `${file}.tmp-${process.pid}-${crypto.randomUUID()}`
  try {
    await writeFile(tmp, content, "utf8")
    await rename(tmp, file)
  } finally {
    await rm(tmp, { force: true }).catch(() => {})
  }
}
