    const baseURL = serve(() => Response.json({ all: [{ id: "local", name: "Local", key: "do-not-expose", options: { apiKey: "[REDACTED]" }, env: ["PRIVATE_KEY"], models: { small: { id: "small", name: "Small", headers: { authorization: "[REDACTED]" } } } }], connected: ["local"], default: { local: "small" } }))
