    OPENCODE_SERVER_PASSWORD: password, OPENCODE_SERVER_USERNAME: "opencode",
  })
  const processUnderTest = Bun.spawn([executable, "serve", "--hostname", "127.0.0.1", "--port", String(port), "--pure"], { cwd: work, env, stdout: "ignore", stderr: "ignore" })
