}

export async function launcherMain(args = process.argv.slice(2)) {
  const { values } = parseArgs({ args, options: { "system-root": { type: "string" }, "portable-root": { type: "string" }, "host-root": { type: "string" }, "no-open": { type: "boolean" } } })
