function hashFile(path: string): string {
  plainFile(path)
  const fd = openSync(path, "r")
  try {
    const hash = createHash("sha256")
    const buffer = Buffer.allocUnsafe(1024 * 1024)
    for (;;) {
      const length = readSync(fd, buffer, 0, buffer.length, null)
