  remember(input: { text: string; scope: string; kind: MemoryKind; sourceIds: number[]; pinned?: boolean; private?: boolean; supersedes?: string }): Memory {
    if (this.sealed) throw new SealedError("已封存：暂停新增记忆与学习")
